'use strict';

const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let index = 0;
const N = data[index++];
const M = data[index++];

const columnSums = Array(M).fill(0);
let answer = Infinity;

for (let i = 0; i < N; i++) {
  let rowSum = 0;
  for (let j = 0; j < M; j++) {
    const value = data[index++];
    rowSum += value;
    columnSums[j] += value;
  }
  answer = Math.min(answer, rowSum);
}

for (const sum of columnSums) {
  answer = Math.min(answer, sum);
}

console.log(answer);
